for fn in ["logs/claude_stream.jsonl", "logs/gemini_stream.jsonl"]:
    try:
        f = open(fn)
    except OSError:
        continue
    for i, line in enumerate(f, 1):
        try:
            obj = json.loads(line)
        except Exception:
            continue

        def walk(o):
            if isinstance(o, str):
                if "def compute_brief_status" in o:
                    yield o
            elif isinstance(o, dict):
                for v in o.values():
                    yield from walk(v)
            elif isinstance(o, list):
                for v in o:
                    yield from walk(v)

        for t in walk(obj):
            if t not in seen:
                seen.add(t)
                print("===== FROM", fn, "line", i, "len", len(t), "=====")
                print(t)
    f.close()

