"""Verification oracle for ``harness.rebuild.discover.module_import_graph``.

``module_import_graph(source_root, modules)`` parses every module in ``modules``
and returns ``{module_rel: set(intra-project module_rels it imports)}``:

  * Only edges to OTHER modules listed in ``modules`` count -- stdlib and
    external third-party imports are ignored.
  * Both top-level and function-local (lazy) imports are considered.
  * Absolute (``import x`` / ``from x import y``) AND relative
    (``from .x import y`` / ``from . import x``) imports resolve.
  * A module never depends on itself.
  * Every module is a key, mapped to a ``set`` (empty when it has no
    intra-project imports).
  * Files that fail to parse (syntax/decode errors) are skipped silently but
    remain keys with an empty edge set.

These tests build tiny real project trees on disk and assert the resulting
graph exactly. They exercise ``module_import_graph`` directly only, so they fail
against a ``NotImplementedError`` stub (non-vacuous).
"""
from __future__ import annotations

from pathlib import Path

from harness.rebuild.discover import module_import_graph


def _make_project(root: Path, files: dict[str, str]) -> None:
    """Write ``{rel_posix_path: source}`` files under ``root`` (stdlib helper)."""
    for rel, src in files.items():
        path = root / rel
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_text(src, encoding="utf-8")


def test_module_import_graph_basic_intra_edge(tmp_path):
    # ``a`` imports ``b`` -> directed edge a->b; ``b`` has no imports.
    _make_project(tmp_path, {
        "a.py": "import b\n",
        "b.py": "x = 1\n",
    })
    graph = module_import_graph(tmp_path, ["a.py", "b.py"])
    assert graph["a.py"] == {"b.py"}
    assert graph["b.py"] == set()


def test_module_import_graph_ignores_external_and_stdlib(tmp_path):
    # None of these names are intra-project modules, so no edges are recorded.
    _make_project(tmp_path, {
        "a.py": "import os\nimport sys\nimport requests\nimport numpy.linalg\n",
    })
    graph = module_import_graph(tmp_path, ["a.py"])
    assert graph == {"a.py": set()}


def test_module_import_graph_no_self_dependency(tmp_path):
    # A module importing its own name (absolute import or from-import) records
    # no self edge.
    _make_project(tmp_path, {
        "a.py": "import a\nfrom a import thing\n",
    })
    graph = module_import_graph(tmp_path, ["a.py"])
    assert graph["a.py"] == set()


def test_module_import_graph_function_local_import_counts(tmp_path):
    # A lazily-imported cross-module dependency (inside a function body) still
    # produces an edge.
    _make_project(tmp_path, {
        "a.py": "def f():\n    import b\n    return b\n",
        "b.py": "y = 2\n",
    })
    graph = module_import_graph(tmp_path, ["a.py", "b.py"])
    assert graph["a.py"] == {"b.py"}
    assert graph["b.py"] == set()


def test_module_import_graph_import_from_absolute(tmp_path):
    # ``from b import thing`` resolves to module ``b``.
    _make_project(tmp_path, {
        "a.py": "from b import thing\n",
        "b.py": "thing = 3\n",
    })
    graph = module_import_graph(tmp_path, ["a.py", "b.py"])
    assert graph["a.py"] == {"b.py"}


def test_module_import_graph_dotted_package_import(tmp_path):
    # ``import pkg.sub`` resolves to the packaged module ``pkg/sub.py``.
    _make_project(tmp_path, {
        "a.py": "import pkg.sub\n",
        "pkg/sub.py": "z = 4\n",
    })
    graph = module_import_graph(tmp_path, ["a.py", "pkg/sub.py"])
    assert graph["a.py"] == {"pkg/sub.py"}


def test_module_import_graph_relative_package_import(tmp_path):
    # A relative ``from .b import helper`` inside package ``pkg`` resolves to the
    # sibling module ``pkg/b.py`` (relative imports are first-class).
    _make_project(tmp_path, {
        "pkg/a.py": "from .b import helper\n",
        "pkg/b.py": "def helper():\n    return 0\n",
    })
    graph = module_import_graph(tmp_path, ["pkg/a.py", "pkg/b.py"])
    assert graph["pkg/a.py"] == {"pkg/b.py"}
    assert graph["pkg/b.py"] == set()


def test_module_import_graph_skips_unparseable_file(tmp_path):
    # A file with a syntax error is skipped (no crash) but still appears as a
    # key with no outgoing edges; a valid importer of it still records the edge.
    _make_project(tmp_path, {
        "broken.py": "def (:\n",
        "b.py": "import broken\n",
    })
    graph = module_import_graph(tmp_path, ["broken.py", "b.py"])
    assert graph["broken.py"] == set()
    assert graph["b.py"] == {"broken.py"}


def test_module_import_graph_missing_file_is_skipped(tmp_path):
    # A module rel that does not exist on disk is skipped (OSError swallowed) but
    # remains a key mapped to an empty set.
    _make_project(tmp_path, {
        "a.py": "x = 0\n",
    })
    graph = module_import_graph(tmp_path, ["a.py", "ghost.py"])
    assert graph["ghost.py"] == set()
    assert graph["a.py"] == set()


def test_module_import_graph_all_modules_present_as_set_keys(tmp_path):
    # Every input module is a key; every value is a set; chained edges resolve.
    _make_project(tmp_path, {
        "a.py": "import b\n",
        "b.py": "import c\n",
        "c.py": "x = 0\n",
    })
    graph = module_import_graph(tmp_path, ["a.py", "b.py", "c.py"])
    assert set(graph) == {"a.py", "b.py", "c.py"}
    assert all(isinstance(v, set) for v in graph.values())
    assert graph["a.py"] == {"b.py"}
    assert graph["b.py"] == {"c.py"}
    assert graph["c.py"] == set()


def test_module_import_graph_multiple_edges_from_one_module(tmp_path):
    # One module importing two distinct intra-project modules records both
    # edges, ignoring an interleaved external import.
    _make_project(tmp_path, {
        "a.py": "import b\nimport os\nfrom c import thing\n",
        "b.py": "p = 1\n",
        "c.py": "thing = 2\n",
    })
    graph = module_import_graph(tmp_path, ["a.py", "b.py", "c.py"])
    assert graph["a.py"] == {"b.py", "c.py"}

