    block = cfg.get("hooks") or {}
    if not isinstance(block, dict):
        raise ConfigError(
            f"hooks: must be a mapping, got {type(block).__name__}"
        )
    allowed = {f.name for f in fields(HooksConfig)}
    unknown = set(block) - allowed
    if unknown:
        raise ConfigError(
            f"hooks: unknown key(s) {sorted(unknown)}; allowed: {sorted(allowed)}"
        )
    return HooksConfig(**block)

